export const ICON_NAMES = Object.keys(ICON_NODES);

const attr = (v: string | number) => String(v).replace(/[&<>"]/g, "");

export function iconSvg(name: string, size = 24): string {
  const node = ICON_NODES[name];
  if (!node) return "";
  const inner = node.map(([tag, a]) => `<${tag} ${Object.entries(a).map(([k, v]) => `${k}="${attr(v)}"`).join(" ")}/>`).join("");
  return `<svg class="ico" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${inner}</svg>`;
}
